export const DOSSIER_COPY = Object.freeze({ en: EN, fr: FR });

/** The dossier's words in `locale` (French when the language has none). */
export function dossierCopy(locale) {
  return Object.hasOwn(DOSSIER_COPY, locale) ? DOSSIER_COPY[locale] : FR;
}
